const msg = ($input.first().json.message?.text || '').trim().toLowerCase();
const chatId = $input.first().json.message?.chat?.id || '';
let type = 'other';
let originalText = $input.first().json.message?.text || '';

if (msg === 'approve' || msg === 'موافق') type = 'approve';
else if (msg === 'export' || msg === 'صدر' || msg === 'تصدير') type = 'export';
else if (msg === 'post' || msg === 'انشر' || msg === 'نشر') type = 'post';
else if (msg === 'أخبار' || msg === 'اخبار' || msg === 'news' || msg === 'عالمي' || msg === 'عالمية' || msg === 'بحث' || msg === 'world') type = 'news';
else if (/^\d+$/.test(msg) && parseInt(msg) >= 1 && parseInt(msg) <= 10) {
  const pickNum = parseInt(msg);
  const staticData = $getWorkflowStaticData('global');
  const cached = staticData.newsCache;
  const cacheAge = Date.now() - (staticData.newsCacheAt || 0);
  if (cached && cacheAge < 3600000 && pickNum <= cached.length) {
    const chosen = cached[pickNum - 1];
    let fullContent = '';
    try {
      const page = await this.helpers.httpRequest({ method: 'GET', url: chosen.link, headers: { 'Accept': 'text/html' } });
      let body = page;
      const articleMatch = body.match(/<article[^>]*>(.*?)<\/article>/s) || body.match(/<div[^>]*class="[^"]*(?:entry-content|post-content|article-content|content-area)[^"]*"[^>]*>(.*?)<\/div>/s);
      if (articleMatch) body = articleMatch[1];
      body = body.replace(/<script[^>]*>.*?<\/script>/gs, '').replace(/<style[^>]*>.*?<\/style>/gs, '').replace(/<[^>]*>/g, ' ').replace(/&[^;]+;/g, ' ').replace(/\s+/g, ' ').trim();
      fullContent = body.substring(0, 2000);
    } catch(e) { fullContent = chosen.desc; }
    originalText = 'اكتب كاروسيل عن هالخبر. لخص النقاط المهمة واذا في خطوات وضحها بشكل مختصر:\n\nالعنوان: ' + chosen.title + '\n\nالمحتوى الكامل:\n' + fullContent + '\n\nالمصدر: ' + chosen.link;
    type = 'topic';
    return [{ json: { type, originalText, chatId } }];
  }
  // Fallback: re-fetch if no cache
  const RSS_FEEDS = [
  'https://www.mentalfloss.com/rss.xml',
  'https://www.smithsonianmag.com/rss/latest_articles/',
  'https://www.iflscience.com/rss',
  'https://www.openculture.com/feed',
  'https://bigthink.com/feed/',
  'https://www.sciencedaily.com/rss/all.xml',
  'https://www.atlasobscura.com/feeds/latest',
  'http://feeds.bbci.co.uk/news/world/rss.xml',
  'https://feeds.npr.org/1001/rss.xml',
  'https://lithub.com/feed/'
];
  const allArticles = [];
  for (const feedUrl of RSS_FEEDS) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET', url: feedUrl,
        headers: { 'Accept': 'application/rss+xml, application/xml, text/xml' }
      });
      const xml = typeof res === 'string' ? res : JSON.stringify(res);
      const items = xml.split('<item>').slice(1, 8);
      for (const item of items) {
        const titleMatch = item.match(/<title><!\[CDATA\[(.+?)\]\]>|<title>(.+?)<\/title>/);
        const linkMatch = item.match(/<link>(.+?)<\/link>|<link><!\[CDATA\[(.+?)\]\]>/);
        const descMatch = item.match(/<description><!\[CDATA\[(.+?)\]\]>|<description>(.+?)<\/description>/s);
        const dateMatch = item.match(/<pubDate>(.+?)<\/pubDate>/);
        const contentMatch = item.match(/<content:encoded><!\[CDATA\[(.+?)\]\]>/s);
        const title = (titleMatch ? (titleMatch[1] || titleMatch[2]) : '').trim();
        const link = (linkMatch ? (linkMatch[1] || linkMatch[2]) : '').trim();
        let desc = (descMatch ? (descMatch[1] || descMatch[2]) : '').trim();
        desc = desc.replace(/<[^>]*>/g, '').replace(/&[^;]+;/g, ' ').substring(0, 120).trim();
        const pubDate = dateMatch ? new Date(dateMatch[1]).getTime() : 0;
        const source = (function(){ try { return feedUrl.split('/')[2].replace('www.','').split('.')[0]; } catch(e){ return 'مصدر'; } })();
        if (title && link) allArticles.push({ title, link, desc, pubDate, source });
      }
    } catch (e) {}
  }
  allArticles.sort((a, b) => b.pubDate - a.pubDate);
  const top5 = allArticles.slice(0, 10);
  if (pickNum <= top5.length) {
    const chosen = top5[pickNum - 1];

    // Fetch full article content
    let fullContent = '';
    try {
      const page = await this.helpers.httpRequest({
        method: 'GET', url: chosen.link,
        headers: { 'Accept': 'text/html' }
      });
      // Extract text from article body
      let body = page;
      // Try to find article/post content area
      const articleMatch = body.match(/<article[^>]*>(.*?)<\/article>/s) || 
                           body.match(/<div[^>]*class="[^"]*(?:entry-content|post-content|article-content|content-area)[^"]*"[^>]*>(.*?)<\/div>/s);
      if (articleMatch) body = articleMatch[1];
      // Remove scripts, styles, tags
      body = body.replace(/<script[^>]*>.*?<\/script>/gs, '');
      body = body.replace(/<style[^>]*>.*?<\/style>/gs, '');
      body = body.replace(/<[^>]*>/g, ' ');
      body = body.replace(/&[^;]+;/g, ' ');
      body = body.replace(/\s+/g, ' ').trim();
      fullContent = body.substring(0, 2000);
    } catch (e) {
      fullContent = chosen.desc;
    }

    originalText = 'اكتب كاروسيل عن هالخبر. لخص النقاط المهمة واذا في خطوات وضحها بشكل مختصر:\n\nالعنوان: ' + chosen.title + '\n\nالمحتوى الكامل:\n' + fullContent + '\n\nالمصدر: ' + chosen.link;
    type = 'topic';
  }
}
else if (/^s\d+:/i.test(msg) || /^caption:/i.test(msg) || /^hashtags:/i.test(msg)) type = 'edit';
else if (msg === 'ريل' || msg === 'reel' || msg === 'ريلز') type = 'reel';
else if (msg === 'أفكار' || msg === 'افكار' || msg === 'اقتراحات' || msg === 'مواضيع' || msg === 'ideas' || msg === 'suggest') type = 'ideas';
else if (msg.length > 2) type = 'topic';

return [{ json: { type, originalText, chatId } }];

function extractText(value) {
  // نص عادي
  if (typeof value === 'string') {
    return value;
  }

  // مصفوفة Claude content blocks
  if (Array.isArray(value)) {
    const textBlock = value.find(
      block =>
        block &&
        block.type === 'text' &&
        typeof block.text === 'string'
    );

    return textBlock?.text || '';
  }

  // كائن يحتوي على content
  if (value && typeof value === 'object') {
    if (typeof value.text === 'string') {
      return value.text;
    }

    if (value.content !== undefined) {
      return extractText(value.content);
    }
  }

  return '';
}

let raw = '';

// أولًا: نحاول قراءة النص المحفوظ في Google Sheets
try {
  const sheetData = $('Save to Sheet').first().json;
  raw = extractText(sheetData.content);
} catch (error) {
  raw = '';
}

// إذا لم يوجد نص صالح في الجدول، نقرأ مباشرة من Claude
if (!raw) {
  try {
    const aiResponse = $('Claude Content API').first().json;
    raw = extractText(aiResponse.content);
  } catch (error) {
    raw = '';
  }
}

// Fallback من مدخل العقدة الحالي
if (!raw) {
  raw = extractText($input.first().json);
}

if (!raw || typeof raw !== 'string') {
  throw new Error(
    'لم يتم العثور على النص النهائي في رد Claude. تأكد أن الرد يحتوي على block من النوع text.'
  );
}

// تنظيف code fences في حال رجع JSON داخل Markdown
raw = raw
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');

if (start === -1 || end === -1 || end <= start) {
  throw new Error(
    'رد Claude لا يحتوي على JSON صالح.\n\nبداية الرد:\n' +
    raw.slice(0, 500)
  );
}

let content;

try {
  content = JSON.parse(raw.slice(start, end + 1));
} catch (error) {
  throw new Error(
    'تعذر تحليل JSON الصادر من Claude: ' +
    error.message +
    '\n\nبداية الرد:\n' +
    raw.slice(0, 700)
  );
}

if (!Array.isArray(content.slides) || content.slides.length === 0) {
  throw new Error('JSON صالح، لكن لا توجد سلايدات داخل slides.');
}

const topic = content.topic || 'موضوع جديد';
const slideCount = content.slides.length;

let preview = '✨ جاهز كاروسيلك من فطين!\n\n';
preview += '📌 الموضوع: ' + topic + '\n';
preview += '🔢 عدد السلايدات: ' + slideCount + '\n\n';

content.slides.forEach((s, i) => {
  preview += '━━━ سلايد ' + (i + 1) + ' (' + (s.type || 'unknown') + ') ━━━\n';

  if (s.type === 'cover') {
    if (s.eyebrow) {
      preview += s.eyebrow + '\n';
    }

    preview += [
      s.title_line1,
      s.title_line2_grad,
      s.title_line3
    ]
      .filter(Boolean)
      .join(' ') + '\n';

    if (s.pill) {
      preview += '🏷 ' + s.pill + '\n';
    }
  }

  else if (s.type === 'stat') {
    preview += '🔢 ' + (s.number || '') + '\n';
    preview += '📍 ' + (s.label || '') + '\n';

    if (s.description) {
      preview += s.description + '\n';
    }
  }

  else if (s.type === 'how_to') {
    preview += '📝 ' + (s.title || '') + '\n';

    (s.steps || []).forEach((step, j) => {
      preview += (j + 1) + '. ' + step + '\n';
    });
  }

  else if (s.type === 'why_matters') {
    preview += '💡 ' + (s.title || '') + '\n';

    (s.points || []).forEach((point, j) => {
      preview += (j + 1) + '. ' + point + '\n';
    });
  }

  else if (s.type === 'save') {
    preview += '🔖 احفظ هالمعلومات:\n';

    (s.points || []).forEach((point, j) => {
      preview += (j + 1) + '. ' + point + '\n';
    });
  }

  else if (s.type === 'warning') {
    preview += '⚠️ ' + (s.title || 'انتبه!') + '\n';

    (s.points || []).forEach((point, j) => {
      preview += (j + 1) + '. ' + point + '\n';
    });
  }

  else if (s.type === 'one_liner') {
    preview += '💬 ' + (s.text || '') + '\n';
  }

  else if (s.type === 'quote') {
    preview += '💬 "' + (s.quote || '') + '"\n';

    if (s.author) {
      preview += '— ' + s.author;

      if (s.role) {
        preview += ' (' + s.role + ')';
      }

      preview += '\n';
    }
  }

  else if (s.type === 'comparison') {
    preview +=
      (s.col1_header || 'الأول') +
      ' vs ' +
      (s.col2_header || 'الثاني') +
      '\n';

    (s.rows || []).forEach(row => {
      if (Array.isArray(row)) {
        preview +=
          '• ' +
          (row[0] || '') +
          ' | ' +
          (row[1] || '') +
          '\n';
      }
    });
  }

  else if (s.type === 'action_prompt') {
    preview += '📣 ' + (s.headline || '') + '\n';
    preview += 'الإجراء: ' + (s.action || 'save') + '\n';
  }

  else if (s.type === 'cta') {
    preview += '❓ ' + (s.question || '') + '\n';

    if (
      Array.isArray(s.options) &&
      s.options.length
    ) {
      s.options.forEach((option, j) => {
        preview +=
          String.fromCharCode(65 + j) +
          ') ' +
          option +
          '\n';
      });
    }

    else if (s.cta_style === 'poll') {
      preview +=
        'A) ' + (s.poll_left || 'موافق') + '\n';

      preview +=
        'B) ' + (s.poll_right || 'مو موافق') + '\n';
    }
  }

  preview += '\n';
});

if (content.caption) {
  preview +=
    '━━━ الكابشن ━━━\n' +
    content.caption +
    '\n\n';
}

if (content.hashtags) {
  preview +=
    '━━━ الهاشتاقات ━━━\n' +
    content.hashtags +
    '\n\n';
}

preview +=
  '━━━━━━━━━━\n' +
  '✅ عجبك؟ أرسل: موافق\n\n' +
  '✏️ تبي تعدّل؟\n' +
  's2: القديم > الجديد\n' +
  'caption: كابشن جديد';

return [
  {
    json: {
      preview,
      chatId: $('Telegram Trigger').first().json.message.chat.id,
      contentJson: JSON.stringify(content),
      topic,
      slideCount,
      caption: content.caption || '',
      hashtags: content.hashtags || ''
    }
  }
];

const items = $input.all();
let lastDraft = null;
let lastIndex = -1;
for (let i = items.length - 1; i >= 0; i--) {
  if (items[i].json.status === 'draft') {
    lastDraft = items[i].json;
    lastIndex = i + 2; // +2 because sheets are 1-indexed and header row
    break;
  }
}
if (!lastDraft) throw new Error('No draft rows found');
return [{ json: { ...lastDraft, rowIndex: lastIndex, contentJson: lastDraft['content'] } }];

// ===== Fateen "تعرف؟" — warm cream / coral editorial (majed style) =====
const C = { bg:'#F1EBE1', bgAlt:'#ECE3D6', coral:'#C1714E', coralSoft:'#DBA789',
  dark:'#2C2A27', muted:'#9A9186', card:'#E9E0D2', line:'rgba(44,42,39,0.12)', white:'#FFFFFF' };
const arNums = ['١','٢','٣','٤','٥','٦','٧','٨','٩','١٠'];
function esc(v){ return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function key(text, word){
  text=esc(text); if(!word) return text; const w=esc(word);
  return text.includes(w)? text.replace(w,`<span class="key">${w}</span>`):text;
}
const BOLT = `<svg viewBox="0 0 24 24" fill="${C.coral}"><path d="M13 2 4 14h6l-1 8 9-12h-6z"/></svg>`;
const BURST = `<svg viewBox="0 0 24 24" fill="none" stroke="${C.coral}" stroke-width="1.6" stroke-linecap="round">${Array.from({length:12}).map((_,i)=>{const a=i*30*Math.PI/180;const x1=12+4*Math.cos(a),y1=12+4*Math.sin(a),x2=12+10*Math.cos(a),y2=12+10*Math.sin(a);return `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}"/>`}).join('')}</svg>`;

function realImage(slide){ const u=slide.image_url||slide.visual_url||slide.background_image; return u?String(u):''; }

function chrome(idx, N){
  let segs=''; for(let i=0;i<N;i++) segs+=`<span class="seg ${i<=idx?'on':''}" style="animation-delay:${i*60}ms"></span>`;
  return `<div class="progress">${segs}</div>
    <div class="page">${arNums[idx]||idx+1} / ${arNums[N-1]||N}</div>
    <div class="label"><span class="ic">${BOLT}</span>تعرف؟</div>
    <div class="handle">فطين</div>`;
}

function numbered(arr){
  return `<div class="nlist">${(arr||[]).slice(0,4).map((p,i)=>
    `<div class="ni" style="--d:${0.25+i*0.12}s"><span class="nn">${arNums[i]||i+1}</span><span class="nt">${esc(p)}</span></div>`
  ).join('')}</div>`;
}
function cards(arr){
  return `<div class="cards">${(arr||[]).slice(0,3).map((p,i)=>
    `<div class="cd" style="--d:${0.25+i*0.12}s"><span class="cic">${BOLT}</span><div class="ct">${esc(p)}</div></div>`
  ).join('')}</div>`;
}

function renderBody(slide){
  const t=slide.type; let kick='تعرف؟', head='', sub='', extra='', icon='', center=true;
  if(t==='cover'){
    kick = slide.eyebrow||'تعرف؟ • تحديث جديد';
    const l1=slide.title_line1||'', l2=slide.title_line2_grad||'', l3=slide.title_line3||'';
    head = [l1?esc(l1):'', l2?`<span class="key">${esc(l2)}</span>`:'', l3?esc(l3):''].filter(Boolean).join('<br>');
    if(slide.pill) sub = esc(slide.pill);
    icon = `<div class="hero-ic pop">${BURST}</div>`;
  } else if(t==='stat'){
    kick='';
    icon=`<div class="stat-ic pop">${BOLT}</div>`;
    head=`<span class="big key">${esc(slide.number||'')}</span><span class="stat-lbl">${esc(slide.label||'')}</span>`;
    if(slide.description) sub=esc(slide.description);
  } else if(t==='one_liner'){ kick='الخلاصة'; head=key(slide.text||'', slide.grad_word);
  } else if(t==='why_matters'){ center=false; kick=''; head=esc(slide.title||'ليش هذا قوي؟'); extra=cards(slide.points);
  } else if(t==='how_to'||t==='save'||t==='warning'){
    center=false; kick=''; head=esc(slide.title || (t==='how_to'?'كيف تبدأ؟':t==='save'?'احفظها':'انتبه'));
    extra=numbered(slide.points||slide.steps);
  } else if(t==='comparison'){ center=false; kick=''; head=`<span class="key">${esc(slide.col1_header||'')}</span> · ${esc(slide.col2_header||'')}`;
    extra=`<div class="nlist">${(slide.rows||[]).slice(0,4).map((r,i)=>`<div class="ni" style="animation-delay:${0.25+i*0.12}s"><span class="nt">${esc(r[0])}</span><span class="sep">—</span><span class="nt">${esc(r[1])}</span></div>`).join('')}</div>`;
  } else if(t==='quote'){ kick='قيل'; head=`<span class="qm">”</span>${esc(slide.quote||'')}`; if(slide.author) sub='— '+esc(slide.author)+(slide.role?' · '+esc(slide.role):'');
  } else if(t==='action_prompt'){ const m={save:'احفظ المنشور',share:'شاركه',like:'عجبك؟'}; kick='قبل تكمل'; icon=`<div class="stat-ic pop">${BOLT}</div>`; head=key(slide.headline||m[slide.action]||m.save, slide.action==='save'?'احفظ':slide.action==='share'?'شاركه':'');
  } else if(t==='cta'){ kick=''; head=key(slide.question||'وش رايك؟', slide.grad_phrase); sub='اكتب جوابك بالتعليقات'; }
  else head=esc(slide.type||'');

  const plain=String(head).replace(/<[^>]+>/g,'');
  const hc=plain.length>34?'h-sm':plain.length>18?'h-md':'';
  const coralHead = ['why_matters','how_to','save','warning','comparison'].includes(t) ? 'ch' : '';
  return `<div class="content ${center?'center':'start'}">
    ${icon}
    ${kick?`<div class="kick rise">${esc(kick)}</div>`:''}
    <h1 class="head rise ${hc} ${coralHead}">${head}</h1>
    ${sub?`<div class="sub rise">${sub}</div>`:''}
    ${extra}
  </div>`;
}

const CSS = `
@font-face{font-family:'Tajawal';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Tajawal';font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Tajawal';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Tajawal';font-style:normal;font-weight:800;font-display:swap;src:url(data:font/woff2;base64,) format('woff2')}
*{margin:0;padding:0;box-sizing:border-box}
@keyframes rise{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:translateY(0)}}
@keyframes pop{0%{opacity:0;transform:scale(.7)}65%{transform:scale(1.06)}100%{opacity:1;transform:scale(1)}}
@keyframes grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.stage{position:relative;width:1080px;height:1350px;overflow:hidden;direction:rtl;
  font-family:'Tajawal',sans-serif;background:${C.bg};color:${C.dark}}
.bg{position:absolute;inset:0;background-size:cover;background-position:center;z-index:0;opacity:.14}
/* chrome */
.progress{position:absolute;top:60px;left:70px;right:70px;z-index:40;display:flex;gap:8px}
.progress .seg{flex:1;height:7px;border-radius:6px;background:rgba(44,42,39,.14);transform-origin:right}
.progress .seg.on{background:${C.coral}}
.page{position:absolute;top:86px;left:70px;z-index:40;font-size:26px;font-weight:700;color:${C.muted};direction:ltr}
.label{position:absolute;top:82px;right:70px;z-index:40;display:flex;align-items:center;gap:10px;font-size:28px;font-weight:800;color:${C.coral}}
.label .ic{width:30px;height:30px;display:inline-block}
.label .ic svg{width:100%;height:100%}
.handle{position:absolute;bottom:88px;left:70px;z-index:40;font-size:28px;font-weight:800;color:${C.muted}}
/* content */
.content{position:absolute;left:96px;right:96px;top:170px;bottom:150px;z-index:30;display:flex;flex-direction:column;justify-content:center;gap:30px}
.content.center{align-items:center;text-align:center}
.content.start{align-items:flex-start;text-align:right}
.hero-ic{width:120px;height:120px;margin-bottom:6px}
.hero-ic svg,.stat-ic svg{width:100%;height:100%}
.stat-ic{width:96px;height:96px}
.kick{font-size:30px;font-weight:700;color:${C.muted};letter-spacing:.3px}
.head{font-size:104px;font-weight:800;line-height:1.28;color:${C.dark};letter-spacing:-1px}
.head.h-md{font-size:80px}
.head.h-sm{font-size:62px}
.head.ch{color:${C.coral}}
.key{color:${C.coral}}
.qm{color:${C.coral};font-weight:800;font-size:1.1em}
.big{display:block;font-size:230px;font-weight:800;line-height:.95;letter-spacing:-6px}
.stat-lbl{display:block;font-size:66px;font-weight:800;color:${C.dark};margin-top:8px}
