// TEST: Skip Cloudinary - use HCTI URLs directly (HCTI URLs are public)
const publicUrls = imageUrls;

// Step 2: Create IG containers SEQUENTIALLY with retry (reliable)
const createContainer = async (publicUrl, i, attempt = 1) => {
  const igRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.instagram.com/v21.0/${igUserId}/media`,
    qs: { image_url: publicUrl, is_carousel_item: 'true', access_token: accessToken },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  if (igRes.body?.id) return igRes.body.id;
  if (attempt < 3) {
    await sleep(2000 * attempt);
    return createContainer(publicUrl, i, attempt + 1);
  }
  throw new Error('IG ITEM ERROR ' + (i+1) + ' after 3 tries | Status: ' + igRes.statusCode + ' | ' + JSON.stringify(igRes.body));
};
const containerIds = [];
for (let i = 0; i < publicUrls.length; i++) {
  containerIds.push(await createContainer(publicUrls[i], i));
  await sleep(800);
}

const carouselRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.instagram.com/v21.0/${igUserId}/media`,
  qs: { media_type: 'CAROUSEL', children: containerIds.join(','), caption, access_token: accessToken },
  returnFullResponse: true,
  ignoreHttpStatusErrors: true
});
if (!carouselRes.body?.id) {
  throw new Error('IG CAROUSEL ERROR | Status: ' + carouselRes.statusCode + ' | ' + JSON.stringify(carouselRes.body));
}
const carousel = carouselRes.body;

await sleep(1000);

const publishedRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://graph.instagram.com/v21.0/${igUserId}/media_publish`,
  qs: { creation_id: carousel.id, access_token: accessToken },
  returnFullResponse: true,
  ignoreHttpStatusErrors: true
});
if (!publishedRes.body?.id) {
  throw new Error('IG PUBLISH ERROR | Status: ' + publishedRes.statusCode + ' | ' + JSON.stringify(publishedRes.body));
}
const published = publishedRes.body;

